<?php use App\Helpers\{View,Csrf};$editing=(bool)$product;?><div class="admin-head"><div><span class="eyebrow">PRODUCTOS</span><h1><?=$editing?'Editar':'Nuevo'?> producto</h1></div><a href="/admin/products">← Volver</a></div><form class="panel form-grid" method="post" enctype="multipart/form-data" action="<?=$editing?'/admin/products/'.$product['id'].'/update':'/admin/products'?>"><?=Csrf::field()?><label>Nombre<input name="name" value="<?=View::e($product['name']??'')?>" required></label><label>Categoría<select name="category_id" required><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=($product&&$product['category_id']==$c['id'])?'selected':''?>><?=View::e($c['name'])?></option><?php endforeach;?></select></label><label class="full">Descripción<textarea name="description" rows="5" required><?=View::e($product['description']??'')?></textarea></label><label>Precio<input type="number" step="0.01" min="0" name="price" value="<?=View::e($product['price']??'')?>" required></label><label>Stock<input type="number" min="0" name="stock" value="<?=View::e($product['stock']??0)?>" required></label><label>Puntos por unidad<input type="number" min="0" name="points_reward" value="<?=View::e($product['points_reward']??0)?>"></label><label>Estado<select name="status"><option>ACTIVE</option><option <?=($product&&$product['status']==='INACTIVE')?'selected':''?>>INACTIVE</option></select></label><label class="full">Imagen JPG/PNG/WEBP<input type="file" name="image" accept="image/jpeg,image/png,image/webp" data-preview><img class="preview" <?php if($product&&$product['image']):?>src="<?=View::e($product['image'])?>"<?php endif;?>></label><label class="check"><input type="checkbox" name="is_featured" <?=($product&&$product['is_featured'])?'checked':''?>> Producto destacado</label><div class="full"><button class="primary">Guardar producto</button></div></form>